import { Container, PointData, TextStyleOptions, Sprite, Text, Texture } from 'pixi.js';

import { Slide } from '../slider';

export interface IInfoPopupSlideStrings {
    title: string;
    points: string[];
}

export interface ISlideTextPoint {
    value: Text;
    bullet?: Text;
}

export interface IInstructionSlideTextStyles {
    default?: TextStyleOptions;
    bullet?: TextStyleOptions;
    title?: TextStyleOptions;
}

export interface ITextPaddings {
    left: number;
    top: number;
    right: number;
}

export interface IInstructionSlideConfig {
    fontStyles?: IInstructionSlideTextStyles;
    imageWidth?: number;
    textPadding?: Partial<ITextPaddings>;
    titleIcon?: {
        texture: Texture;
        width: number;
    };
}

export class InstructionSlide extends Slide {
    private screenImage: Sprite;
    private screenText: Container;
    private titleIcon: Sprite;
    private titleText!: Text;
    private textPoints: ISlideTextPoint[] = [];

    private strings: IInfoPopupSlideStrings;
    private imageAreaWidthMultiplier: number;
    private titleIconWidthMultiplier: number;
    private textPaddingMultipliers: ITextPaddings;
    private textPadding!: ITextPaddings;

    constructor(imageTexture: Texture, strings: IInfoPopupSlideStrings, config: IInstructionSlideConfig = {}) {
        super();

        this.strings = strings;
        this.imageAreaWidthMultiplier = config.imageWidth ?? 0.55;
        this.titleIconWidthMultiplier = config.titleIcon?.width ?? 0;
        this.textPaddingMultipliers = {
            left: config.textPadding?.left ?? 0,
            top: config.textPadding?.top ?? 0,
            right: config.textPadding?.right ?? 0
        };

        this.screenImage = new Sprite(imageTexture);
        this.screenImage.anchor.set(0, 0.5);
        this.addChild(this.screenImage);

        this.screenText = new Container();
        this.addChild(this.screenText);

        this.titleIcon = new Sprite(config.titleIcon?.texture);
        this.screenText.addChild(this.titleIcon);

        this.createTextSections(config.fontStyles);
    }

    public resize(width: number, height: number, offset: PointData): void {
        super.resize(width, height, offset);

        const imageAreaWidth = width * this.imageAreaWidthMultiplier;
        const textAreaWidth = width - imageAreaWidth;

        const widthScale = imageAreaWidth / this.screenImage.texture.width;
        const heightScale = height / this.screenImage.texture.height;
        const scale = Math.min(widthScale, heightScale);
        this.screenImage.scale.set(scale);
        this.screenImage.x = -(width * 0.5);
        this.screenText.x = (width * 0.5) - (textAreaWidth);
        this.screenText.y = -(height * 0.5);

        this.textPadding = {
            left: textAreaWidth * this.textPaddingMultipliers.left,
            top: height * this.textPaddingMultipliers.top,
            right: textAreaWidth * this.textPaddingMultipliers.right
        };
        const wordWrapWidth = textAreaWidth - this.textPadding.left - this.textPadding.right;

        this.titleIcon.width = textAreaWidth * this.titleIconWidthMultiplier;
        this.titleIcon.scale.y = this.titleIcon.scale.x;
        this.titleIcon.x = this.textPadding.left;
        this.titleIcon.y = this.textPadding.top;

        this.titleText.style.wordWrapWidth = wordWrapWidth - (this.titleIcon.width * 1.2);
        this.titleText.x = this.titleIcon.x + (this.titleIcon.width * 1.2);
        this.titleText.y = this.titleIcon.y + (this.titleText.style.padding ?? 0);

        const titleHeight = Math.max(this.titleIcon.height, this.titleText.height);
        const firstYOffset = this.titleText.y + titleHeight;
        this.textPoints.forEach((point: ISlideTextPoint, index: number, array: ISlideTextPoint[]) => {
            let xOffset = 0;
            const yOffset = index === 0 ? firstYOffset : array[index - 1].value.y + array[index - 1].value.height;
            if (point.bullet) {
                this.sizeAndPositionTextItem(point.bullet, wordWrapWidth, xOffset, yOffset);
                xOffset += point.bullet.width * 1.5;
            }
            this.sizeAndPositionTextItem(point.value, wordWrapWidth, xOffset, yOffset);
        });
    }

    private sizeAndPositionTextItem(item: Text, wrapWidth: number, xOffset: number, yOffset: number): void {
        item.style.wordWrapWidth = wrapWidth - xOffset;
        item.x = this.textPadding.left + xOffset;
        item.y = yOffset;
    }

    private createTextSections(textStyles?: IInstructionSlideTextStyles): void {
        this.titleText = new Text({ text: this.strings.title, style: textStyles?.title });
        this.screenText.addChild(this.titleText);

        this.strings.points?.forEach((point: string) => {
            const bullet = '\u2022';
            const newBullet = new Text({ text: bullet, style: textStyles?.bullet });
            const newPoint = new Text({ text: point, style: textStyles?.default });

            this.textPoints.push({ value: newPoint, bullet: newBullet });
            this.screenText.addChild(newBullet);
            this.screenText.addChild(newPoint);
        });
    }
}
